INSERT INTO Beer (name, brewer) VALUES ('Lager', 'BrewCo');
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Alice', 'The Pub', 5);
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bob', 'The Tavern', 5);
